/// MightBothParticipate: false iff the two groups are in different alternatives of a
/// common disjunction.
fn might_both_participate(a: &[(u32, u32)], b: &[(u32, u32)]) -> bool {
    let n = a.len().min(b.len());
    for i in 0..n {
        if a[i].0 != b[i].0 {
            return true;
        }
        if a[i].1 != b[i].1 {
            return false;
        }
    }
    true
}

