//! Compiles the parsed AST into a program for the backtracking VM.

use super::charset::CharSet;
use super::parser::{Ast, Node, NodeId, INF};

/// A character set prepared for fast membership tests.
#[derive(Clone, Debug)]
pub(crate) struct MatchSet {
    ascii: u128,
    ranges: Vec<(u32, u32)>,
}

impl MatchSet {
    pub(crate) fn new(set: &CharSet) -> MatchSet {
        let mut ascii = 0u128;
        for &(a, b) in &set.r {
            if a >= 128 {
                break;
            }
            for c in a..=b.min(127) {
                ascii |= 1u128 << c;
            }
        }
        MatchSet { ascii, ranges: set.r.clone() }
    }

    #[inline(always)]
    pub(crate) fn contains(&self, c: u32) -> bool {
        if c < 128 {
            return (self.ascii >> c) & 1 != 0;
        }
        let r = &self.ranges;
        let mut lo = 0usize;
        let mut hi = r.len();
        while lo < hi {
            let mid = (lo + hi) / 2;
            let (a, b) = r[mid];
            if c < a {
                hi = mid;
            } else if c > b {
                lo = mid + 1;
            } else {
                return true;
            }
        }
        false
    }

    pub(crate) fn charset(&self) -> CharSet {
        CharSet { r: self.ranges.clone() }
    }
}

/// Single-character matcher used by simple repeats.
#[derive(Clone, Copy, Debug)]
pub(crate) enum CharMatcher {
    Char(u32),
    Set(u32),
}

#[derive(Clone, Debug)]
pub(crate) enum Inst {
    Match,
    Char(u32),
    CharBack(u32),
    Set(u32),
    SetBack(u32),
    /// Exact code-unit string (forward only, no surrogates); index into `strs`.
    Str(u32),
    LineStart,
    LineStartM,
    LineEnd,
    LineEndM,
    /// (negated, unicode-ignoreCase word characters)
    WordB(bool, bool),
    Jmp(u32),
    /// Try the first target, on failure the second.
    Split(u32, u32),
    /// Capture slot write: slot := pos (undo-logged)
    Save(u32),
    /// Reset capture groups lo..=hi to undefined
    ResetCaps(u32, u32),
    /// regs[reg] := 0
    CounterInit(u32),
    LoopHead { reg: u32, min: u32, max: u32, greedy: bool, exit: u32 },
    /// Increments the counter (and performs the empty check if `pos_reg` != NONE)
    LoopTail { reg: u32, pos_reg: u32, min: u32, head: u32 },
    SavePos(u32),
    /// Fails if pos == regs[reg]
    CheckEmpty(u32),
    Repeat { m: CharMatcher, min: u32, max: u32, greedy: bool, back: bool },
    BackRef { refs: u32, icase: bool, back: bool },
    LookStart { negative: bool, end: u32 },
    LookEnd,
    Fail,
}

pub(crate) const NONE: u32 = u32::MAX;

pub(crate) struct Program {
    pub(crate) insts: Vec<Inst>,
    pub(crate) sets: Vec<MatchSet>,
    pub(crate) strs: Vec<Vec<u16>>,
    pub(crate) backrefs: Vec<Vec<u32>>,
    pub(crate) nregs: usize,
    pub(crate) ncap: usize,
    pub(crate) unicode: bool,
    /// Pattern can only match at position 0 (leading non-multiline `^`).
    pub(crate) anchored: bool,
    /// Pattern starts with multiline `^` in every alternative.
    pub(crate) line_anchored: bool,
    /// Possible first code units of a match (None = unknown / may be empty).
    pub(crate) first: Option<MatchSet>,
    /// Literal prefix (code units) every match starts with.
    pub(crate) prefix: Vec<u16>,
    /// Leading greedy unbounded single-char repeat (index of its set/char matcher):
    /// a failed attempt at p lets the search skip to the end of the run.
    pub(crate) lead_repeat: Option<(CharMatcher, u32)>,
}

pub(crate) struct Compiler<'a> {
    ast: &'a Ast,
    insts: Vec<Inst>,
    sets: Vec<MatchSet>,
    strs: Vec<Vec<u16>>,
    backrefs: Vec<Vec<u32>>,
    nregs: u32,
    unicode: bool,
}

/// Repetition counts above this are rejected for non-simple atoms.
const MAX_COMPLEX_REPEAT: u32 = 1000;

impl<'a> Compiler<'a> {
    pub(crate) fn compile(ast: &'a Ast, unicode: bool) -> Result<Program, String> {
        let mut c = Compiler { ast, insts: Vec::new(), sets: Vec::new(), strs: Vec::new(), backrefs: Vec::new(), nregs: 0, unicode };
        c.sets = ast.sets.iter().map(MatchSet::new).collect();
        c.check_repeats()?;
        c.emit(ast.root, false);
        c.insts.push(Inst::Match);
        let anchored = c.starts_with_anchor(ast.root, false);
        let line_anchored = !anchored && c.starts_with_anchor(ast.root, true);
        let first = c.first_set(ast.root).map(|s| MatchSet::new(&s));
        let prefix = c.literal_prefix();
        let lead_repeat = c.leading_repeat(ast.root);
        Ok(Program {
            insts: c.insts,
            sets: c.sets,
            strs: c.strs,
            backrefs: c.backrefs,
            nregs: c.nregs as usize,
            ncap: ast.ncap as usize,
            unicode,
            anchored,
            line_anchored,
            first,
            prefix,
            lead_repeat,
        })
    }

    fn node(&self, id: NodeId) -> &'a Node {
        &self.ast.nodes[id as usize]
    }

    fn reg(&mut self) -> u32 {
        self.nregs += 1;
        self.nregs - 1
    }

    fn pc(&self) -> u32 {
        self.insts.len() as u32
    }

    fn push(&mut self, i: Inst) -> u32 {
        self.insts.push(i);
        self.pc() - 1
    }

    /// Is `id` a single-character matcher (for simple repeats)?
    fn simple_matcher(&self, id: NodeId) -> Option<CharMatcher> {
        match self.node(id) {
            Node::Char(c) => Some(CharMatcher::Char(*c)),
            Node::Set(s) => Some(CharMatcher::Set(*s)),
            Node::StringClass(i) => {
                let sc = &self.ast.string_classes[*i as usize];
                if sc.strings.is_empty() && !sc.has_empty {
                    Some(CharMatcher::Set(sc.singles))
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    /// "repetition count too large" check (performed after parsing, in source order).
    fn check_repeats(&self) -> Result<(), String> {
        for n in &self.ast.nodes {
            if let Node::Quant { min, max, child, .. } = n {
                if self.simple_matcher(*child).is_none() && (*min > MAX_COMPLEX_REPEAT || (*max != INF && *max > MAX_COMPLEX_REPEAT)) {
                    return Err("repetition count too large".into());
                }
            }
        }
        Ok(())
    }

    pub(crate) fn can_be_empty(&self, id: NodeId) -> bool {
        match self.node(id) {
            Node::Empty | Node::LineStart(_) | Node::LineEnd(_) | Node::WordBoundary(..) | Node::Look { .. } | Node::BackRef(..) | Node::NamedRef(..) => true,
            Node::Char(_) | Node::Set(_) => false,
            Node::StringClass(i) => self.ast.string_classes[*i as usize].has_empty,
            Node::Group(_, c) => self.can_be_empty(*c),
            Node::Quant { min, max, child, .. } => *min == 0 || *max == 0 || self.can_be_empty(*child),
            Node::Seq(v) => v.iter().all(|&c| self.can_be_empty(c)),
            Node::Alt(v) => v.iter().any(|&c| self.can_be_empty(c)),
        }
    }

    fn emit(&mut self, id: NodeId, back: bool) {
        match self.node(id) {
            Node::Empty => {}
            Node::Char(c) => {
                let c = *c;
                self.push(if back { Inst::CharBack(c) } else { Inst::Char(c) });
            }
            Node::Set(s) => {
                let s = *s;
                self.push(if back { Inst::SetBack(s) } else { Inst::Set(s) });
            }
            Node::StringClass(i) => self.emit_string_class(*i, back),
            Node::LineStart(m) => {
                let m = *m;
                self.push(if m { Inst::LineStartM } else { Inst::LineStart });
            }
            Node::LineEnd(m) => {
                let m = *m;
                self.push(if m { Inst::LineEndM } else { Inst::LineEnd });
            }
            Node::WordBoundary(neg, ui) => {
                let (neg, ui) = (*neg, *ui);
                self.push(Inst::WordB(neg, ui));
            }
            Node::BackRef(groups, icase) => {
                let icase = *icase;
                self.backrefs.push(groups.clone());
                let refs = (self.backrefs.len() - 1) as u32;
                self.push(Inst::BackRef { refs, icase, back });
            }
            Node::NamedRef(..) => unreachable!("unresolved named reference"),
            Node::Group(cap, child) => {
                let child = *child;
                match cap {
                    Some(g) => {
                        let g = *g;
                        // forward: start slot first; backward: end slot first
                        let (first, second) = if back { (2 * g + 1, 2 * g) } else { (2 * g, 2 * g + 1) };
                        self.push(Inst::Save(first));
                        self.emit(child, back);
                        self.push(Inst::Save(second));
                    }
                    None => self.emit(child, back),
                }
            }
            Node::Look { behind, negative, child } => {
                let (behind, negative, child) = (*behind, *negative, *child);
                let start = self.push(Inst::LookStart { negative, end: 0 });
                self.emit(child, behind);
                self.push(Inst::LookEnd);
                let end = self.pc();
                if let Inst::LookStart { end: e, .. } = &mut self.insts[start as usize] {
                    *e = end;
                }
            }
            Node::Seq(items) => {
                let items = items.clone();
                if back {
                    for &it in items.iter().rev() {
                        self.emit(it, back);
                    }
                } else {
                    let mut i = 0;
                    while i < items.len() {
                        // merge runs of literal chars into a string instruction
                        let mut j = i;
                        let mut units: Vec<u16> = Vec::new();
                        while j < items.len() {
                            if let Node::Char(c) = self.node(items[j]) {
                                let c = *c;
                                if (0xD800..=0xDFFF).contains(&c) {
                                    break;
                                }
                                if c >= 0x10000 {
                                    let v = c - 0x10000;
                                    units.push((0xD800 + (v >> 10)) as u16);
                                    units.push((0xDC00 + (v & 0x3FF)) as u16);
                                } else {
                                    units.push(c as u16);
                                }
                                j += 1;
                            } else {
                                break;
                            }
                        }
                        if j - i >= 2 {
                            self.strs.push(units);
                            let k = (self.strs.len() - 1) as u32;
                            self.push(Inst::Str(k));
                            i = j;
                        } else {
                            self.emit(items[i], back);
                            i += 1;
                        }
                    }
                }
            }
            Node::Alt(alts) => {
                let alts = alts.clone();
                let mut jumps = Vec::new();
                for (k, &a) in alts.iter().enumerate() {
                    if k + 1 < alts.len() {
                        let split = self.push(Inst::Split(0, 0));
                        let body = self.pc();
                        self.emit(a, back);
                        jumps.push(self.push(Inst::Jmp(0)));
                        let next = self.pc();
                        self.insts[split as usize] = Inst::Split(body, next);
                    } else {
                        self.emit(a, back);
                    }
                }
                let end = self.pc();
                for j in jumps {
                    self.insts[j as usize] = Inst::Jmp(end);
                }
            }
            Node::Quant { min, max, greedy, child, cap_lo, cap_hi, .. } => {
                let (min, mut max, greedy, child, cap_lo, cap_hi) = (*min, *max, *greedy, *child, *cap_lo, *cap_hi);
                if max != INF && max < min {
                    max = min;
                }
                if max == 0 {
                    return;
                }
                if let Some(m) = self.simple_matcher(child) {
                    if min == 1 && max == 1 {
                        self.emit(child, back);
                    } else {
                        self.push(Inst::Repeat { m, min, max, greedy, back });
                    }
                    return;
                }
                self.emit_loop(child, min, max, greedy, cap_lo, cap_hi, back);
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_loop(&mut self, child: NodeId, min: u32, max: u32, greedy: bool, cap_lo: u32, cap_hi: u32, back: bool) {
        let has_caps = cap_lo <= cap_hi;
        let nullable = self.can_be_empty(child);
        if min == 0 && (max == INF || max == 1) {
            // star / optional
            let pos_reg = if nullable { self.reg() } else { NONE };
            let head = self.push(Inst::Split(0, 0));
            let body = self.pc();
            if pos_reg != NONE {
                self.push(Inst::SavePos(pos_reg));
            }
            if has_caps {
                self.push(Inst::ResetCaps(cap_lo, cap_hi));
            }
            self.emit(child, back);
            if pos_reg != NONE {
                self.push(Inst::CheckEmpty(pos_reg));
            }
            if max == INF {
                self.push(Inst::Jmp(head));
            }
            let exit = self.pc();
            self.insts[head as usize] = if greedy { Inst::Split(body, exit) } else { Inst::Split(exit, body) };
            return;
        }
        if min == 1 && max == INF && !nullable {
            let body = self.pc();
            if has_caps {
                self.push(Inst::ResetCaps(cap_lo, cap_hi));
            }
            self.emit(child, back);
            let split = self.push(Inst::Split(0, 0));
            let exit = self.pc();
            self.insts[split as usize] = if greedy { Inst::Split(body, exit) } else { Inst::Split(exit, body) };
            return;
        }
        // general counted loop
        let reg = self.reg();
        let pos_reg = if nullable && max > min { self.reg() } else { NONE };
        self.push(Inst::CounterInit(reg));
        let head = self.push(Inst::LoopHead { reg, min, max, greedy, exit: 0 });
        if pos_reg != NONE {
            self.push(Inst::SavePos(pos_reg));
        }
        if has_caps {
            self.push(Inst::ResetCaps(cap_lo, cap_hi));
        }
        self.emit(child, back);
        self.push(Inst::LoopTail { reg, pos_reg, min, head });
        let exit = self.pc();
        if let Inst::LoopHead { exit: e, .. } = &mut self.insts[head as usize] {
            *e = exit;
        }
    }

    fn emit_string_class(&mut self, idx: u32, back: bool) {
        let sc = &self.ast.string_classes[idx as usize];
        let icase = sc.icase;
        let strings = sc.strings.clone();
        let has_empty = sc.has_empty;
        let singles = sc.singles;
        let singles_empty = self.ast.sets[singles as usize].is_empty();
        // alternatives: strings (longest first), empty string, singles
        enum Alt {
            Str(Vec<u32>),
            Empty,
            Singles,
        }
        let mut alts: Vec<Alt> = strings.into_iter().map(Alt::Str).collect();
        if has_empty {
            alts.push(Alt::Empty);
        }
        if !singles_empty {
            alts.push(Alt::Singles);
        }
        if alts.is_empty() {
            self.push(Inst::Fail);
            return;
        }
        let mut jumps = Vec::new();
        let n = alts.len();
        for (k, a) in alts.into_iter().enumerate() {
            let split = if k + 1 < n { Some(self.push(Inst::Split(0, 0))) } else { None };
            let body = self.pc();
            match a {
                Alt::Str(s) => {
                    let chars: Vec<u32> = if back { s.iter().rev().copied().collect() } else { s.clone() };
                    for c in chars {
                        self.emit_char(c, icase, back);
                    }
                }
                Alt::Empty => {}
                Alt::Singles => {
                    self.push(if back { Inst::SetBack(singles) } else { Inst::Set(singles) });
                }
            }
            if let Some(split) = split {
                jumps.push(self.push(Inst::Jmp(0)));
                let next = self.pc();
                self.insts[split as usize] = Inst::Split(body, next);
            }
        }
        let end = self.pc();
        for j in jumps {
            self.insts[j as usize] = Inst::Jmp(end);
        }
    }

    fn emit_char(&mut self, c: u32, icase: bool, back: bool) {
        if icase {
            let cls = if self.unicode { super::charset::scf_classes() } else { super::charset::legacy_classes() };
            if let Some(members) = cls.class_of(c) {
                let set = CharSet::from_ranges(members.iter().map(|&m| (m, m)).collect());
                self.sets.push(MatchSet::new(&set));
                let s = (self.sets.len() - 1) as u32;
                self.push(if back { Inst::SetBack(s) } else { Inst::Set(s) });
                return;
            }
        }
        self.push(if back { Inst::CharBack(c) } else { Inst::Char(c) });
    }

    // -----------------------------------------------------------------------
    // Search optimizations
    // -----------------------------------------------------------------------

    /// Does every match start with `^` (multiline or not, as requested)?
    fn starts_with_anchor(&self, id: NodeId, multiline: bool) -> bool {
        match self.node(id) {
            Node::LineStart(m) => *m == multiline,
            Node::Group(_, c) => self.starts_with_anchor(*c, multiline),
            Node::Seq(v) => !v.is_empty() && self.starts_with_anchor(v[0], multiline),
            Node::Alt(v) => v.iter().all(|&a| self.starts_with_anchor(a, multiline)),
            Node::Quant { min, child, .. } => *min >= 1 && self.starts_with_anchor(*child, multiline),
            _ => false,
        }
    }

    /// Conservative set of code units that can start a match; None if unknown or the
    /// pattern may match the empty string at the start position.
    fn first_set(&self, root: NodeId) -> Option<CharSet> {
        let (set, nullable) = self.first_of(root, 0)?;
        if nullable {
            return None;
        }
        Some(set)
    }

    /// Returns (first code units, may be empty) for a node.
    fn first_of(&self, id: NodeId, depth: u32) -> Option<(CharSet, bool)> {
        if depth > 64 {
            return None;
        }
        match self.node(id) {
            Node::Empty => Some((CharSet::new(), true)),
            Node::Char(c) => Some((CharSet::single(first_unit(*c)), false)),
            Node::Set(s) => Some((units_of(&self.ast.sets[*s as usize]), false)),
            Node::StringClass(i) => {
                let sc = &self.ast.string_classes[*i as usize];
                if sc.icase {
                    return None;
                }
                let mut set = units_of(&self.ast.sets[sc.singles as usize]);
                for s in &sc.strings {
                    set.add_set(&CharSet::single(first_unit(s[0])));
                }
                Some((set, sc.has_empty))
            }
            Node::LineStart(_) | Node::LineEnd(_) | Node::WordBoundary(..) => Some((CharSet::new(), true)),
            Node::Look { .. } | Node::BackRef(..) | Node::NamedRef(..) => None,
            Node::Group(_, c) => self.first_of(*c, depth + 1),
            Node::Quant { min, max, child, .. } => {
                if *max == 0 {
                    return Some((CharSet::new(), true));
                }
                let (s, n) = self.first_of(*child, depth + 1)?;
                Some((s, n || *min == 0))
            }
            Node::Seq(v) => {
                let mut acc = CharSet::new();
                for &it in v {
                    let (s, n) = self.first_of(it, depth + 1)?;
                    acc.add_set(&s);
                    if !n {
                        return Some((acc, false));
                    }
                }
                Some((acc, true))
            }
            Node::Alt(v) => {
                let mut acc = CharSet::new();
                let mut nullable = false;
                for &a in v {
                    let (s, n) = self.first_of(a, depth + 1)?;
                    acc.add_set(&s);
                    nullable |= n;
                }
                Some((acc, nullable))
            }
        }
    }

    /// Literal code-unit prefix of the compiled program (from leading Str/Char insts).
    fn literal_prefix(&self) -> Vec<u16> {
        let mut out = Vec::new();
        for inst in &self.insts {
            match inst {
                Inst::Str(k) => out.extend_from_slice(&self.strs[*k as usize]),
                Inst::Char(c) => {
                    let c = *c;
                    if (0xD800..=0xDFFF).contains(&c) {
                        break;
                    }
                    if c >= 0x10000 {
                        let v = c - 0x10000;
                        out.push((0xD800 + (v >> 10)) as u16);
                        out.push((0xDC00 + (v & 0x3FF)) as u16);
                    } else {
                        out.push(c as u16);
                    }
                }
                Inst::Save(_) => continue,
                _ => break,
            }
        }
        out
    }

    /// Leading greedy, unbounded simple repeat outside any group: (matcher, min).
    fn leading_repeat(&self, root: NodeId) -> Option<(CharMatcher, u32)> {
        let first = match self.node(root) {
            Node::Seq(v) => v[0],
            _ => root,
        };
        if let Node::Quant { min, max, greedy: true, child, .. } = self.node(first) {
            if *max == INF {
                if let Some(m) = self.simple_matcher(*child) {
                    return Some((m, *min));
                }
            }
        }
        None
    }
}

fn first_unit(c: u32) -> u32 {
    if c >= 0x10000 {
        0xD800 + ((c - 0x10000) >> 10)
    } else {
        c
    }
}

/// Maps a code point set to the set of possible first code units.
fn units_of(set: &CharSet) -> CharSet {
    let mut v: Vec<(u32, u32)> = Vec::new();
    for &(a, b) in &set.r {
        if b < 0x10000 {
            v.push((a, b));
        } else {
            if a < 0x10000 {
                v.push((a, 0xFFFF));
            }
            let lo = a.max(0x10000);
            v.push((first_unit(lo), first_unit(b)));
        }
    }
    CharSet::from_ranges(v)
}

//! Backtracking VM with an explicit backtrack stack and undo log (no recursion).

use super::charset::{legacy_canon, scf};
use super::compiler::{CharMatcher, Inst, Program, NONE};

const UNDEF: u32 = u32::MAX;

#[derive(Clone, Copy, Debug)]
enum Bt {
    /// Resume at `pc` with position `pos`.
    Branch { pc: u32, pos: u32 },
    /// Restore a capture slot.
    Cap { slot: u32, old: u32 },
    /// Restore a register.
    Reg { reg: u32, old: u32 },
    /// Greedy simple repeat: may give back characters down to `min_pos`.
    Greedy { pc: u32, pos: u32, min_pos: u32 },
    /// Lazy simple repeat: may take more characters (count so far).
    Lazy { pc: u32, pos: u32, count: u32 },
    /// Lookaround frame.
    Look { end: u32, pos: u32, negative: bool },
}

pub(crate) struct Vm {
    stack: Vec<Bt>,
    pub(crate) caps: Vec<u32>,
    regs: Vec<u32>,
}

#[inline(always)]
fn is_lt(c: u32) -> bool {
    c == 0x0A || c == 0x0D || c == 0x2028 || c == 0x2029
}

#[inline(always)]
fn is_word(c: u32, ui: bool) -> bool {
    (c < 128 && {
        let b = c as u8;
        b.is_ascii_alphanumeric() || b == b'_'
    }) || (ui && (c == 0x17F || c == 0x212A))
}

/// Reads the character at `pos` going forward: (char, next pos).
#[inline(always)]
fn fwd<const U: bool>(input: &[u16], pos: usize) -> Option<(u32, usize)> {
    let c = *input.get(pos)? as u32;
    if U && (c & 0xFC00) == 0xD800 {
        if let Some(&d) = input.get(pos + 1) {
            let d = d as u32;
            if (d & 0xFC00) == 0xDC00 {
                return Some((0x10000 + ((c - 0xD800) << 10) + (d - 0xDC00), pos + 2));
            }
        }
    }
    Some((c, pos + 1))
}

/// Reads the character before `pos` going backward: (char, new pos).
#[inline(always)]
fn bwd<const U: bool>(input: &[u16], pos: usize) -> Option<(u32, usize)> {
    if pos == 0 {
        return None;
    }
    let c = input[pos - 1] as u32;
    if U && (c & 0xFC00) == 0xDC00 && pos >= 2 {
        let h = input[pos - 2] as u32;
        if (h & 0xFC00) == 0xD800 {
            return Some((0x10000 + ((h - 0xD800) << 10) + (c - 0xDC00), pos - 2));
        }
    }
    Some((c, pos - 1))
}

impl Vm {
    pub(crate) fn new() -> Vm {
        Vm { stack: Vec::new(), caps: Vec::new(), regs: Vec::new() }
    }

    #[inline(always)]
    fn matches(prog: &Program, m: CharMatcher, c: u32) -> bool {
        match m {
            CharMatcher::Char(x) => c == x,
            CharMatcher::Set(s) => prog.sets[s as usize].contains(c),
        }
    }

    /// Runs the program anchored at `start`. On success the capture slots are in `caps`.
    pub(crate) fn run(&mut self, prog: &Program, input: &[u16], start: usize) -> bool {
        if prog.unicode {
            self.run_impl::<true>(prog, input, start)
        } else {
            self.run_impl::<false>(prog, input, start)
        }
    }

    fn run_impl<const U: bool>(&mut self, prog: &Program, input: &[u16], start: usize) -> bool {
        let nslots = 2 * (prog.ncap + 1);
        self.caps.clear();
        self.caps.resize(nslots, UNDEF);
        self.regs.clear();
        self.regs.resize(prog.nregs, 0);
        self.stack.clear();
        let insts = &prog.insts[..];
        let len = input.len();
        let mut pc: usize = 0;
        let mut pos: usize = start;
        let stack = &mut self.stack;
        let caps = &mut self.caps;
        let regs = &mut self.regs;
        'main: loop {
            let ok: bool = match &insts[pc] {
                Inst::Match => {
                    caps[0] = start as u32;
                    caps[1] = pos as u32;
                    return true;
                }
                Inst::Char(c) => match fwd::<U>(input, pos) {
                    Some((x, np)) if x == *c => {
                        pos = np;
                        pc += 1;
                        true
                    }
                    _ => false,
                },
                Inst::CharBack(c) => match bwd::<U>(input, pos) {
                    Some((x, np)) if x == *c => {
                        pos = np;
                        pc += 1;
                        true
                    }
                    _ => false,
                },
                Inst::Set(s) => match fwd::<U>(input, pos) {
                    Some((x, np)) if prog.sets[*s as usize].contains(x) => {
                        pos = np;
                        pc += 1;
                        true
                    }
                    _ => false,
                },
                Inst::SetBack(s) => match bwd::<U>(input, pos) {
                    Some((x, np)) if prog.sets[*s as usize].contains(x) => {
                        pos = np;
                        pc += 1;
                        true
                    }
                    _ => false,
                },
                Inst::Str(k) => {
                    let s = &prog.strs[*k as usize];
                    if pos + s.len() <= len && &input[pos..pos + s.len()] == &s[..] {
                        // in unicode mode the string must not end in the middle of a pair
                        if U && pos + s.len() < len && (s[s.len() - 1] & 0xFC00) == 0xD800 && (input[pos + s.len()] & 0xFC00) == 0xDC00 {
                            false
                        } else {
                            pos += s.len();
                            pc += 1;
                            true
                        }
                    } else {
                        false
                    }
                }
                Inst::LineStart => {
                    if pos == 0 {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::LineStartM => {
                    if pos == 0 || is_lt(input[pos - 1] as u32) {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::LineEnd => {
                    if pos == len {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::LineEndM => {
                    if pos == len || is_lt(input[pos] as u32) {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::WordB(neg, ui) => {
                    let a = pos > 0 && is_word(input[pos - 1] as u32, *ui);
                    let b = pos < len && is_word(input[pos] as u32, *ui);
                    if (a != b) != *neg {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::Jmp(t) => {
                    pc = *t as usize;
                    true
                }
                Inst::Split(a, b) => {
                    stack.push(Bt::Branch { pc: *b, pos: pos as u32 });
                    pc = *a as usize;
                    true
                }
                Inst::Save(slot) => {
                    let slot = *slot as usize;
                    stack.push(Bt::Cap { slot: slot as u32, old: caps[slot] });
                    caps[slot] = pos as u32;
                    pc += 1;
                    true
                }
                Inst::ResetCaps(lo, hi) => {
                    for slot in (2 * *lo as usize)..=(2 * *hi as usize + 1) {
                        if caps[slot] != UNDEF {
                            stack.push(Bt::Cap { slot: slot as u32, old: caps[slot] });
                            caps[slot] = UNDEF;
                        }
                    }
                    pc += 1;
                    true
                }
                Inst::CounterInit(r) => {
                    let r = *r as usize;
                    stack.push(Bt::Reg { reg: r as u32, old: regs[r] });
                    regs[r] = 0;
                    pc += 1;
                    true
                }
                Inst::LoopHead { reg, min, max, greedy, exit } => {
                    let k = regs[*reg as usize];
                    if k < *min {
                        pc += 1;
                    } else if *max != u32::MAX && k >= *max {
                        pc = *exit as usize;
                    } else if *greedy {
                        stack.push(Bt::Branch { pc: *exit, pos: pos as u32 });
                        pc += 1;
                    } else {
                        stack.push(Bt::Branch { pc: pc as u32 + 1, pos: pos as u32 });
                        pc = *exit as usize;
                    }
                    true
                }
                Inst::LoopTail { reg, pos_reg, min, head } => {
                    let r = *reg as usize;
                    let k = regs[r];
                    if *pos_reg != NONE && k >= *min && regs[*pos_reg as usize] == pos as u32 {
                        false
                    } else {
                        stack.push(Bt::Reg { reg: r as u32, old: k });
                        regs[r] = k.saturating_add(1);
                        pc = *head as usize;
                        true
                    }
                }
                Inst::SavePos(r) => {
                    let r = *r as usize;
                    stack.push(Bt::Reg { reg: r as u32, old: regs[r] });
                    regs[r] = pos as u32;
                    pc += 1;
                    true
                }
                Inst::CheckEmpty(r) => {
                    if regs[*r as usize] == pos as u32 {
                        false
                    } else {
                        pc += 1;
                        true
                    }
                }
                Inst::Repeat { m, min, max, greedy, back } => {
                    let (m, min, max) = (*m, *min, *max);
                    if *greedy {
                        let mut count = 0u32;
                        let mut p = pos;
                        let mut min_pos = if min == 0 { pos } else { usize::MAX };
                        if !*back {
                            while count < max {
                                match fwd::<U>(input, p) {
                                    Some((c, np)) if Self::matches(prog, m, c) => {
                                        p = np;
                                        count += 1;
                                        if count == min {
                                            min_pos = p;
                                        }
                                    }
                                    _ => break,
                                }
                            }
                        } else {
                            while count < max {
                                match bwd::<U>(input, p) {
                                    Some((c, np)) if Self::matches(prog, m, c) => {
                                        p = np;
                                        count += 1;
                                        if count == min {
                                            min_pos = p;
                                        }
                                    }
                                    _ => break,
                                }
                            }
                        }
                        if count < min {
                            false
                        } else {
                            if count > min {
                                stack.push(Bt::Greedy { pc: pc as u32, pos: p as u32, min_pos: min_pos as u32 });
                            }
                            pos = p;
                            pc += 1;
                            true
                        }
                    } else {
                        let mut count = 0u32;
                        let mut p = pos;
                        let mut ok = true;
                        while count < min {
                            let r = if !*back { fwd::<U>(input, p) } else { bwd::<U>(input, p) };
                            match r {
                                Some((c, np)) if Self::matches(prog, m, c) => {
                                    p = np;
                                    count += 1;
                                }
                                _ => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        if !ok {
                            false
                        } else {
                            if count < max {
                                stack.push(Bt::Lazy { pc: pc as u32, pos: p as u32, count });
                            }
                            pos = p;
                            pc += 1;
                            true
                        }
                    }
                }
                Inst::BackRef { refs, icase, back } => {
                    let groups = &prog.backrefs[*refs as usize];
                    let mut span = None;
                    for &g in groups {
                        let (s, e) = (caps[2 * g as usize], caps[2 * g as usize + 1]);
                        if s != UNDEF && e != UNDEF {
                            span = Some((s as usize, e as usize));
                            break;
                        }
                    }
                    match span {
                        None => {
                            pc += 1;
                            true
                        }
                        Some((s, e)) => match backref_match::<U>(input, s, e, pos, *icase, *back) {
                            Some(np) => {
                                pos = np;
                                pc += 1;
                                true
                            }
                            None => false,
                        },
                    }
                }
                Inst::LookStart { negative, end } => {
                    stack.push(Bt::Look { end: *end, pos: pos as u32, negative: *negative });
                    pc += 1;
                    true
                }
                Inst::LookEnd => {
                    // find the innermost lookaround frame
                    let mut i = stack.len();
                    loop {
                        i -= 1;
                        if let Bt::Look { .. } = stack[i] {
                            break;
                        }
                    }
                    let (end, lpos, negative) = match stack[i] {
                        Bt::Look { end, pos, negative } => (end, pos, negative),
                        _ => unreachable!(),
                    };
                    if negative {
                        // body matched: undo everything above the frame and fail
                        while stack.len() > i + 1 {
                            match stack.pop().unwrap() {
                                Bt::Cap { slot, old } => caps[slot as usize] = old,
                                Bt::Reg { reg, old } => regs[reg as usize] = old,
                                _ => {}
                            }
                        }
                        stack.pop();
                        false
                    } else {
                        // keep undo records, drop choice points and the frame
                        let mut w = i;
                        for k in i + 1..stack.len() {
                            match stack[k] {
                                Bt::Cap { .. } | Bt::Reg { .. } => {
                                    stack[w] = stack[k];
                                    w += 1;
                                }
                                _ => {}
                            }
                        }
                        stack.truncate(w);
                        pos = lpos as usize;
                        pc = end as usize;
                        true
                    }
                }
                Inst::Fail => false,
            };
            if ok {
                continue;
            }
            // backtrack
            loop {
                let top = match stack.last_mut() {
                    None => return false,
                    Some(t) => t,
                };
                match *top {
                    Bt::Branch { pc: p, pos: q } => {
                        stack.pop();
                        pc = p as usize;
                        pos = q as usize;
                        continue 'main;
                    }
                    Bt::Cap { slot, old } => {
                        caps[slot as usize] = old;
                        stack.pop();
                    }
                    Bt::Reg { reg, old } => {
                        regs[reg as usize] = old;
                        stack.pop();
                    }
                    Bt::Greedy { pc: p, pos: q, min_pos } => {
                        let back = matches!(insts[p as usize], Inst::Repeat { back: true, .. });
                        // give back one character
                        let np = if !back {
                            let q = q as usize;
                            let mut np = q - 1;
                            if U && np > min_pos as usize && (input[np] & 0xFC00) == 0xDC00 && (input[np - 1] & 0xFC00) == 0xD800 {
                                np -= 1;
                            }
                            np
                        } else {
                            let q = q as usize;
                            let mut np = q + 1;
                            if U && np < min_pos as usize && (input[q] & 0xFC00) == 0xD800 && (input[np] & 0xFC00) == 0xDC00 {
                                np += 1;
                            }
                            np
                        };
                        if np as u32 == min_pos {
                            stack.pop();
                        } else if let Some(Bt::Greedy { pos, .. }) = stack.last_mut() {
                            *pos = np as u32;
                        }
                        pc = p as usize + 1;
                        pos = np;
                        continue 'main;
                    }
                    Bt::Lazy { pc: p, pos: q, count } => {
                        let (m, max, back) = match insts[p as usize] {
                            Inst::Repeat { m, max, back, .. } => (m, max, back),
                            _ => unreachable!(),
                        };
                        let r = if !back { fwd::<U>(input, q as usize) } else { bwd::<U>(input, q as usize) };
                        match r {
                            Some((c, np)) if Self::matches(prog, m, c) => {
                                let ncount = count + 1;
                                if ncount >= max {
                                    stack.pop();
                                } else if let Some(Bt::Lazy { pos, count, .. }) = stack.last_mut() {
                                    *pos = np as u32;
                                    *count = ncount;
                                }
                                pc = p as usize + 1;
                                pos = np;
                                continue 'main;
                            }
                            _ => {
                                stack.pop();
                            }
                        }
                    }
                    Bt::Look { end, pos: q, negative } => {
                        stack.pop();
                        if negative {
                            // body failed: negative lookaround succeeds
                            pc = end as usize;
                            pos = q as usize;
                            continue 'main;
                        }
                    }
                }
            }
        }
    }
}

/// Matches the captured text input[s..e] at `pos` (forward) or ending at `pos` (backward).
fn backref_match<const U: bool>(input: &[u16], s: usize, e: usize, pos: usize, icase: bool, back: bool) -> Option<usize> {
    let n = e - s;
    let (from, to) = if back {
        if n > pos {
            return None;
        }
        (pos - n, pos)
    } else {
        if pos + n > input.len() {
            return None;
        }
        (pos, pos + n)
    };
    if U {
        // must not split surrogate pairs at the boundaries
        if back && from > 0 && n > 0 && (input[from] & 0xFC00) == 0xDC00 && (input[from - 1] & 0xFC00) == 0xD800 {
            return None;
        }
        if !back && to < input.len() && n > 0 && (input[to - 1] & 0xFC00) == 0xD800 && (input[to] & 0xFC00) == 0xDC00 {
            return None;
        }
    }
    if !icase {
        if input[s..e] == input[from..to] {
            return Some(if back { from } else { to });
        }
        return None;
    }
    if U {
        let mut i = s;
        let mut j = from;
        while i < e {
            let (a, ni) = fwd::<true>(&input[..e], i)?;
            let (b, nj) = fwd::<true>(&input[..to], j)?;
            if a != b && scf(a) != scf(b) {
                return None;
            }
            i = ni;
            j = nj;
        }
        if j != to {
            return None;
        }
    } else {
        for k in 0..n {
            let a = input[s + k] as u32;
            let b = input[from + k] as u32;
            if a != b && legacy_canon(a) != legacy_canon(b) {
                return None;
            }
        }
    }
    Some(if back { from } else { to })
}

//! ECMAScript regular expressions (ES2025) for lumen.
