#![allow(dead_code)]
mod regexp;
mod unicode;

use std::io::{BufRead, Write};

/// Minimal JSON value parser (enough for test case files).
#[derive(Debug, Clone)]
enum J {
    Str(Vec<u16>),
    Num(f64),
    Arr(Vec<J>),
    Null,
    Bool(bool),
}

fn parse_json(s: &[u16], i: &mut usize) -> J {
    while *i < s.len() && (s[*i] == b' ' as u16 || s[*i] == b'\t' as u16) {
        *i += 1;
    }
    let c = s[*i];
    if c == b'"' as u16 {
        *i += 1;
        let mut out = Vec::new();
        loop {
            let c = s[*i];
            *i += 1;
            if c == b'"' as u16 {
                break;
            }
            if c == b'\\' as u16 {
                let e = s[*i];
                *i += 1;
                match e as u8 {
                    b'n' => out.push(10),
                    b'r' => out.push(13),
                    b't' => out.push(9),
                    b'b' => out.push(8),
                    b'f' => out.push(12),
                    b'u' => {
                        let h: String = s[*i..*i + 4].iter().map(|&u| u as u8 as char).collect();
                        out.push(u16::from_str_radix(&h, 16).unwrap());
                        *i += 4;
                    }
                    _ => out.push(e),
                }
            } else {
                out.push(c);
            }
        }
        return J::Str(out);
    }
    if c == b'[' as u16 {
        *i += 1;
        let mut v = Vec::new();
        loop {
            while s[*i] == b' ' as u16 {
                *i += 1;
            }
            if s[*i] == b']' as u16 {
                *i += 1;
                break;
            }
            v.push(parse_json(s, i));
            while s[*i] == b' ' as u16 {
                *i += 1;
            }
            if s[*i] == b',' as u16 {
                *i += 1;
            }
        }
        return J::Arr(v);
    }
    if c == b'n' as u16 {
        *i += 4;
        return J::Null;
    }
    if c == b't' as u16 {
        *i += 4;
        return J::Bool(true);
    }
    if c == b'f' as u16 {
        *i += 5;
        return J::Bool(false);
    }
    let start = *i;
    while *i < s.len() && (s[*i] == b'-' as u16 || s[*i] == b'.' as u16 || (s[*i] >= b'0' as u16 && s[*i] <= b'9' as u16) || s[*i] == b'e' as u16) {
        *i += 1;
    }
    let t: String = s[start..*i].iter().map(|&u| u as u8 as char).collect();
    J::Num(t.parse().unwrap())
}

fn json_str(s: &[u16]) -> String {
    let mut out = String::from("\"");
    for ch in char::decode_utf16(s.iter().copied()) {
        match ch {
            Ok('"') => out.push_str("\\\""),
            Ok('\\') => out.push_str("\\\\"),
            Ok('\n') => out.push_str("\\n"),
            Ok('\r') => out.push_str("\\r"),
            Ok('\t') => out.push_str("\\t"),
            Ok(c) if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            Ok(c) => out.push(c),
            Err(e) => out.push_str(&format!("\\u{:04x}", e.unpaired_surrogate())),
        }
    }
    out.push('"');
    out
}

fn span_json(s: Option<(usize, usize)>) -> String {
    match s {
        None => "null".into(),
        Some((a, b)) => format!("[{},{}]", a, b),
    }
}

fn run_case(pat: &[u16], flags: &[u16], input: &[u16], li: usize) -> String {
    let f = match regexp::parse_flags(flags) {
        Ok(f) => f,
        Err(e) => return format!("E:{}", e),
    };
    let re = match regexp::compile(pat, f) {
        Ok(r) => r,
        Err(e) => return format!("E:{}", e),
    };
    let li = if f.global || f.sticky { li } else { 0 };
    match re.exec(input, li) {
        None => "N".into(),
        Some(spans) => {
            let arr: Vec<String> = spans.iter().map(|&s| span_json(s)).collect();
            let names = re.group_names();
            let g = if names.is_empty() {
                "-".to_string()
            } else {
                let mut parts = Vec::new();
                for (name, idxs) in &names {
                    let mut v = None;
                    for &k in idxs {
                        if spans[k].is_some() {
                            v = spans[k];
                            break;
                        }
                    }
                    if let Some(v) = v {
                        parts.push(format!("{}:{}", json_str(name), span_json(Some(v))));
                    }
                }
                format!("{{{}}}", parts.join(","))
            };
            format!("M:[{}]|{}", arr.join(","), g)
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() >= 2 && args[1] == "bench" {
        bench(&args[2..]);
        return;
    }
    let file = std::fs::File::open(&args[1]).unwrap();
    let out = std::io::stdout();
    let mut out = out.lock();
    for line in std::io::BufReader::new(file).lines() {
        let line = line.unwrap();
        if line.trim().is_empty() {
            continue;
        }
        let u: Vec<u16> = line.encode_utf16().collect();
        let mut i = 0;
        let v = parse_json(&u, &mut i);
        if let J::Arr(a) = v {
            let get = |k: usize| match &a[k] {
                J::Str(s) => s.clone(),
                _ => Vec::new(),
            };
            let li = match a.get(3) {
                Some(J::Num(n)) => *n as usize,
                _ => 0,
            };
            let r = run_case(&get(0), &get(1), &get(2), li);
            writeln!(out, "{}", r).unwrap();
        }
    }
}

fn bench(args: &[String]) {
    let pat: Vec<u16> = args[0].encode_utf16().collect();
    let flags: Vec<u16> = args[1].encode_utf16().collect();
    let kind = args[2].as_str();
    let n: usize = args[3].parse().unwrap();
    let input: Vec<u16> = match kind {
        "ab" => "ab".repeat(n).encode_utf16().collect(),
        "abc" => ("ab".repeat(n) + "c").encode_utf16().collect(),
        "a" => "a".repeat(n).encode_utf16().collect(),
        "ax" => ("a".repeat(n) + "x").encode_utf16().collect(),
        "sp" => (" ".repeat(n) + "a").encode_utf16().collect(),
        "text" => "The quick brown fox jumps over the lazy dog. ".repeat(n).encode_utf16().collect(),
        _ => kind.repeat(n).encode_utf16().collect(),
    };
    let f = regexp::parse_flags(&flags).unwrap();
    let re = regexp::compile(&pat, f).unwrap();
    let t = std::time::Instant::now();
    let mut count = 0;
    let mut li = 0;
    let mut last = None;
    loop {
        let r = re.exec(&input, li);
        match r {
            None => break,
            Some(s) => {
                count += 1;
                let (a, b) = s[0].unwrap();
                last = Some((a, b));
                if !f.global {
                    break;
                }
                li = if b == a { b + 1 } else { b };
                if li > input.len() {
                    break;
                }
            }
        }
    }
    println!("matches={} last={:?} time={:?}", count, last, t.elapsed());
}
