                }
                q = nq;
            }
            if q > s {
                s = q;
            }
        }
        if s >= len {
            return false;
        }
        s += if unicode && s + 1 < len && is_high(input[s]) && is_low(input[s + 1]) { 2 } else { 1 };
    }
}

