241	    /// Counts capturing groups (class/escape aware) and detects named groups (naive
242	    /// "(?<" scan, exactly like the original).
243	    fn prescan(&mut self) {
244	        let s = &self.src;
245	        let n = s.len();
246	        let mut i = 0;
247	        let mut count = 0u32;
248	        let mut class_depth = 0u32;
249	        let lt = '<' as u32;
250	        let q = '?' as u32;
251	        while i < n {
252	            let c = s[i];
253	            if c == '\\' as u32 {
254	                i += 2;
255	                continue;
256	            }
257	            if class_depth > 0 {
258	                if c == ']' as u32 {
259	                    class_depth -= 1;
260	                } else if c == '[' as u32 && self.v {
261	                    class_depth += 1;
262	                }
263	            } else if c == '[' as u32 {
264	                class_depth = 1;
265	            } else if c == '(' as u32 {
266	                if i + 1 >= n || s[i + 1] != q {
267	                    count += 1;
268	                } else if i + 2 < n && s[i + 2] == lt && (i + 3 >= n || (s[i + 3] != '=' as u32 && s[i + 3] != '!' as u32)) {
269	                    count += 1;
270	                }
271	            }
272	            i += 1;
273	        }
274	        self.total_caps = count;
275	        if !self.named {
276	            for i in 0..n {
277	                if s[i] == '(' as u32 && i + 2 < n && s[i + 1] == q && s[i + 2] == lt && (i + 3 >= n || (s[i + 3] != '=' as u32 && s[i + 3] != '!' as u32)) {
