1	//! Backtracking VM with an explicit backtrack stack and undo log (no recursion).
2	
3	use super::charset::{legacy_canon, scf};
4	use super::compiler::{CharMatcher, Inst, Program, NONE};
5	
6	const UNDEF: u32 = u32::MAX;
7	
8	/// Recursion depth limit of the original runtime's matcher (in its frame units).
9	pub(crate) const DEPTH_LIMIT: u32 = 2998;
10	/// Per-attempt step budget of the original runtime's matcher.
11	pub(crate) const STEP_BUDGET: u64 = 2_000_000;
12	/// Step weights (calibrated against the original's budget on pathological patterns):
13	/// a frame of the emulated recursive matcher, a frame of a simple repeat or lookaround,
14	/// a backtrack resume, and a loop back-edge of an unbounded loop with a non-nullable body.
15	const STEP_PER_DEPTH: u64 = 2;
16	const STEP_PER_LIGHT_DEPTH: u64 = 1;
17	const STEP_PER_RESUME: u64 = 1;
18	const STEP_PER_ITERATION: u64 = 1;
19	
20	#[derive(Clone, Copy, Debug)]
21	enum Bt {
22	    /// Resume at `pc` with position `pos` (and emulated depth).
23	    Branch { pc: u32, pos: u32, depth: u32 },
24	    /// Restore a capture slot.
25	    Cap { slot: u32, old: u32 },
26	    /// Restore a register.
27	    Reg { reg: u32, old: u32 },
28	    /// Greedy simple repeat: may give back characters down to `min_pos`.
29	    Greedy { pc: u32, pos: u32, min_pos: u32, depth: u32 },
30	    /// Lazy simple repeat: may take more characters (count so far).
31	    Lazy { pc: u32, pos: u32, count: u32, depth: u32 },
32	    /// Lookaround frame.
33	    Look { end: u32, pos: u32, depth: u32, negative: bool, leak: bool },
34	}
35	
36	pub(crate) struct Vm {
37	    stack: Vec<Bt>,
38	    pub(crate) caps: Vec<u32>,
39	    regs: Vec<u32>,
40	}
41	
42	#[inline(always)]
43	fn is_lt(c: u32) -> bool {
44	    c == 0x0A || c == 0x0D || c == 0x2028 || c == 0x2029
45	}
46	
47	#[inline(always)]
48	fn is_word(c: u32, ui: bool) -> bool {
49	    (c < 128 && {
50	        let b = c as u8;
51	        b.is_ascii_alphanumeric() || b == b'_'
52	    }) || (ui && (c == 0x17F || c == 0x212A))
53	}
54	
55	/// Reads the character at `pos` going forward: (char, next pos).
56	#[inline(always)]
57	fn fwd<const U: bool>(input: &[u16], pos: usize) -> Option<(u32, usize)> {
58	    let c = *input.get(pos)? as u32;
59	    if U && (c & 0xFC00) == 0xD800 {
60	        if let Some(&d) = input.get(pos + 1) {
61	            let d = d as u32;
62	            if (d & 0xFC00) == 0xDC00 {
63	                return Some((0x10000 + ((c - 0xD800) << 10) + (d - 0xDC00), pos + 2));
64	            }
65	        }
66	    }
67	    Some((c, pos + 1))
68	}
69	
70	/// Reads the character before `pos` going backward: (char, new pos).
71	#[inline(always)]
72	fn bwd<const U: bool>(input: &[u16], pos: usize) -> Option<(u32, usize)> {
73	    if pos == 0 {
74	        return None;
75	    }
76	    let c = input[pos - 1] as u32;
77	    if U && (c & 0xFC00) == 0xDC00 && pos >= 2 {
78	        let h = input[pos - 2] as u32;
79	        if (h & 0xFC00) == 0xD800 {
80	            return Some((0x10000 + ((h - 0xD800) << 10) + (c - 0xDC00), pos - 2));
81	        }
82	    }
83	    Some((c, pos - 1))
84	}
85	
86	impl Vm {
87	    pub(crate) fn new() -> Vm {
88	        Vm { stack: Vec::new(), caps: Vec::new(), regs: Vec::new() }
89	    }
90	
91	    #[inline(always)]
92	    fn matches(prog: &Program, m: CharMatcher, c: u32) -> bool {
93	        match m {
94	            CharMatcher::Char(x) => c == x,
95	            CharMatcher::Set(s) => prog.sets[s as usize].contains(c),
96	        }
97	    }
